head.script:
scwin.onpageload = function () {
    let arr = [
        { "item" : "노트북", "amount" : "1250000", "price" : "1234.5" },
        { "item" : "모니터", "amount" : "380000", "price" : "89000" }
    ];
    dlt_a.setJSON(arr);
    dlt_b.setJSON(arr);
};

// advancedExcelDownload 실행 + 서버로 전송된 useDataFormat, Column 별 excelFormat 출력
scwin.download = function (grd, name, sUseDataFormat) {
    let sBody = "";
    let fnSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
        let objInput = this.querySelector("input[name=xmlValue]");
        if (sBody === "" && objInput) {
            sBody = objInput.value;
        }
        return fnSubmit.apply(this, arguments);
    };
    try {
        grd.advancedExcelDownload({ "fileName" : "grid_" + name, "extension" : "xlsx", "useDataFormat" : sUseDataFormat });
    } finally {
        HTMLFormElement.prototype.submit = fnSubmit;
    }
    let objFlag = sBody.match(/hashkey='useDataFormat' value='([^']*)'/);
    scwin.setReturnValue("[" + name + "] 전송 useDataFormat : " + (objFlag ? objFlag[1] : "(미전달)")
        + " / 전송 excelFormat : amount=" + scwin.getSentFormat(sBody, "amount")
        + ", price=" + scwin.getSentFormat(sBody, "price"));
};

// 전송 XML 의 Body 영역에서 Column 의 excelFormat 을 읽는다
scwin.getSentFormat = function (sBody, sColId) {
    let nStart = sBody.indexOf("<w2:gBody");
    let sBodyXml = (nStart < 0) ? "" : sBody.substring(nStart, sBody.indexOf("</w2:gBody>", nStart));
    let arrTag = sBodyXml.split("<w2:column");
    for (let i = 1; i < arrTag.length; i++) {
        let sTag = arrTag[i].substring(0, arrTag[i].indexOf(">"));
        if (sTag.indexOf(' id="' + sColId + '"') < 0) {
            continue;
        }
        let objFmt = sTag.match(/ excelFormat="([^"]*)"/);
        if (!objFmt || objFmt[1] === "") {
            return "(없음)";
        }
        return objFmt[1].replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&");
    }
    return "(미전달)";
};

scwin.btn_a_onclick = function () { scwin.download(grd_a, "A", "true"); };
scwin.btn_b_onclick = function () { scwin.download(grd_b, "B", "false"); };

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
